head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF24601.xml";
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 오늘날짜

/*
 * init()
 */
scwin.fn_init = function() {
    $c.stf.setObjectValue(edt_Date, scwin.vCurDate);
};


/*
  지수산출기관 조회
*/
scwin.fn_list_sync1 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_PROD_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.idx.calc.inst.select.list.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_Date); // 조회일자		

    dts_List1.DataID = encodeURI(url);
    dts_List1.Reset();
    $c.cm.ShowWin(grd_List1);
};


/*
  기초시장 조회
*/
scwin.fn_list_sync2 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_PROD_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.idx.mkt.clss.select.list.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_Date) + // 조회일자		
        "&{P}param02=" + $c.stf.getObjectValue(edt_Date) + // 조회일자	
        "&{P}param03=" + $c.stf.getObjectValue(edt_Date) + // 조회일자	
        "&{P}param04=" + $c.stf.getObjectValue(edt_Date); // 조회일자			  
    dts_List2.DataID = encodeURI(url);
    dts_List2.Reset();
    $c.cm.ShowWin(grd_List2);
};


/*
	  기초시장 조회
	*/
scwin.fn_list_sync3 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_PROD_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.idx.asst.clss.select.list.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_Date) + // 조회일자		
        "&{P}param02=" + $c.stf.getObjectValue(edt_Date) + // 조회일자	
        "&{P}param03=" + $c.stf.getObjectValue(edt_Date) + // 조회일자	
        "&{P}param04=" + $c.stf.getObjectValue(edt_Date); // 조회일자			  
    dts_List3.DataID = encodeURI(url);
    dts_List3.Reset();
    $c.cm.ShowWin(grd_List3);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync1();
    scwin.fn_list_sync2();
    scwin.fn_list_sync3();
};
scwin.dts_List1_OnLoadError = function() {
    $c.stf.alert_error(dts_List1);
};
scwin.btn_Date_onclick = function() {
    popUpCalendar2(edt_Date);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_init();
    scwin.fn_list_sync1();
    scwin.fn_list_sync2();
    scwin.fn_list_sync3();
};
scwin.btn_Excel1_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
    $c.data.downloadGridViewExcel(grd_List1, "ETF,ETN 상품유형", "", "3");
};
scwin.btn_Excel2_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
    $c.data.downloadGridViewExcel(grd_List2, "ETF,ETN 상품유형", "", "3");
};
scwin.btn_Excel3_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
    $c.data.downloadGridViewExcel(grd_List3, "ETF,ETN 상품유형", "", "3");
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List1);
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List2);
};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List3);
};
